    const axis = (pair: [Key, Key] | null): number =>
      pair ? (pressed.has(pair[0]) ? 1 : 0) - (pressed.has(pair[1]) ? 1 : 0) : 0;
    return {
      thrust: axis(s.thrust),
      yaw: axis(s.yaw),
      pitch: axis(s.pitch),
      roll: axis(s.roll),
      up: s.vtol && pressed.has(s.vtol) ? 1 : 0,
    };
  }

